import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Negative load relative to the mean load, but scaled by the arriving job's size: -(loads - mean) / (mean + job + eps)."""
    loads = np.asarray(loads, dtype=float)
    mean = loads.mean()
    return -(loads - mean) / (mean + float(job) + 1e-9)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """If the arriving job exceeds every current load, score machines by -load/max_load (least-loaded wins); otherwise 0."""
    mx = float(np.max(loads))
    if job > mx:
        denom = mx if mx > 0.0 else 1.0
        return -loads / denom
    return np.zeros_like(loads)

import numpy as np

def feature(job, loads, past_jobs, jobs_left):
    """Gate on remaining heavy-tail mass times best-fit (load+job capped at T)/T."""
    past = np.asarray(past_jobs, dtype=float)
    n = past.size
    m = loads.size
    if n >= 5:
        med = np.median(past)
        frac = float(np.mean(past > 4.0 * med)) if med > 1e-9 else 0.0
    else:
        frac = 0.0
    gate = float(np.clip(jobs_left * frac / 3.0, 0.0, 1.0))
    done = float(np.sum(past))
    mean_past = done / n if n > 0 else float(job)
    max_past = float(np.max(past)) if n > 0 else float(job)
    T = max(max_past, (done + job + jobs_left * mean_past) / m)
    if T <= 1e-9:
        return np.zeros(m)
    score = gate * np.minimum(loads + job, T) / T
    return np.clip(score, -1.0, 1.0)
